import { defineCollection } from "astro:content"

import { pageSchema } from "@/schemas/page"
import { pageLoader } from "@/lib/page-loader"

export const collections = {
  pages: defineCollection({ loader: pageLoader(), schema: pageSchema }),
}

---
import { siteConfig } from "@/site.config"

import {
  getPageAlternates,
  getPageBreadcrumbs,
  getPageLocale,
  getPages,
  getPageUrl,
  type Page,
} from "@/lib/pages"
import { getStructuredData } from "@/lib/seo"
import {
  Layout,
  LayoutBody,
  LayoutHead,
  LayoutMain,
} from "@/components/ui/layout"

type Props = { page: Page }
const { page } = Astro.props
const pages = await getPages()
const locale = getPageLocale(page)
const breadcrumbs = getPageBreadcrumbs(pages, page)
---

<Layout lang={locale}>
  <LayoutHead
    name={siteConfig.name}
    title={page.data.title}
    description={page.data.description}
    image={page.data.image}
    {...page.data.seo}
    canonical={page.data.seo?.canonical ?? getPageUrl(page)}
    alternates={getPageAlternates(pages, page)}
    structuredData={getStructuredData(page, {
      name: siteConfig.name,
      locale,
      breadcrumbs,
    })}
  />
  <LayoutBody>
    <LayoutMain class="mx-auto w-full max-w-5xl gap-8 px-6 py-12">
      <slot />
    </LayoutMain>
  </LayoutBody>
</Layout>

import { existsSync } from "node:fs"
import { glob } from "astro/loaders"

// Files are URLs. `services.md` and `services/index.md` would both become
// /services/, which Astro's glob loader only warns about, so reject it here.
export const pageLoader = (base = "src/content/pages") => {
  const files = new Map<string, string>()
  return glob({
    base,
    pattern: "**/[^_]*.{md,mdx}",
    generateId: ({ entry, base }) => {
      const id = entry.replace(/\.mdx?$/, "").replace(/\/index$/, "")
      const other = files.get(id)
      if (
        other &&
        other !== entry &&
        existsSync(new URL(encodeURI(other), base))
      )
        throw new Error(
          `Page route collision: "${other}" and "${entry}" both map to "/${id}/".`
        )
      files.set(id, entry)
      return id
    },
  })
}

import { i18n, site } from "astro:config/server"
import { getCollection, type CollectionEntry } from "astro:content"

export type Page = CollectionEntry<"pages">

if (!site) {
  throw new Error(
    "Set `site` in astro.config. Page URLs, canonicals, and the sitemap need it."
  )
}

export const siteUrl = site

// Locale folders come from Astro's own i18n config, so there is nothing to mirror.
const defaultLocale = i18n?.defaultLocale ?? "en"
const locales =
  i18n?.locales.map((locale) =>
    typeof locale === "string" ? locale : locale.path
  ) ?? []
const prefixDefaultLocale =
  typeof i18n?.routing === "object" && i18n.routing.prefixDefaultLocale

export const getPageHref = (page: Pick<Page, "id">) =>
  page.id === "index" ? "/" : `/${page.id}/`

export const getPageUrl = (page: Pick<Page, "id">) =>
  new URL(getPageHref(page), siteUrl).href

export const getMarkdownHref = (href: string) =>
  href === "/" ? "/index.md" : `${href.replace(/\/$/, "")}.md`

export const getPageLocale = (page: Pick<Page, "id">) => {
  const [first] = page.id.split("/")
  return locales.includes(first) ? first : defaultLocale
}

const getHomeId = (locale: string) =>
  locale === defaultLocale && !prefixDefaultLocale ? "index" : locale

// One rule for sitemap inclusion, hreflang alternates, and search. Robots meta
// stays explicit: layouts pass seo.noindex and seo.nofollow to the head as is.
export const isIndexable = (page: Page) =>
  !page.data.seo?.noindex &&
  (page.data.seo?.canonical ?? getPageUrl(page)) === getPageUrl(page)

export const getPages = async () => {
  const pages = await getCollection("pages")
  const byLocaleKey = new Map<string, Page>()
  const byKey = new Map<string, Page>()
  for (const page of pages) {
    const [first] = page.id.split("/")
    if (prefixDefaultLocale && !locales.includes(first))
      throw new Error(
        `Page "${page.id}" must live in a locale folder (${locales.join(", ")}).`
      )
    if (!prefixDefaultLocale && first === defaultLocale)
      throw new Error(
        `Page "${page.id}" must live at the root; the default locale has no folder.`
      )
    const key = page.data.translationKey
    if (!key) continue
    const localeKey = `${getPageLocale(page)}:${key}`
    const twin = byLocaleKey.get(localeKey)
    if (twin)
      throw new Error(
        `Pages "${twin.id}" and "${page.id}" share translationKey "${key}" in one locale.`
      )
    byLocaleKey.set(localeKey, page)
    const other = byKey.get(key)
    if (other && other.data.type !== page.data.type)
      throw new Error(
        `Translations "${other.id}" and "${page.id}" must use the same page type.`
      )
    byKey.set(key, page)
  }
  return pages
}

export const getPageChildren = (pages: Page[], parent: Pick<Page, "id">) => {
  const prefix = parent.id === "index" ? "" : `${parent.id}/`
  const locale = getPageLocale(parent)
  return pages.filter(
    (page) =>
      page.id !== parent.id &&
      page.id.startsWith(prefix) &&
      !page.id.slice(prefix.length).includes("/") &&
      getPageLocale(page) === locale
  )
}

export const getOverviewEntries = (pages: Page[], page: Page) => {
  const locale = getPageLocale(page)
  const entries = page.data.type === "overview" ? page.data.entries : undefined
  if (!entries)
    return getPageChildren(pages, page).sort((a, b) =>
      a.data.title.localeCompare(b.data.title, locale)
    )
  return entries.map(({ id }) => {
    const entry = pages.find((candidate) => candidate.id === id)
    if (!entry)
      throw new Error(`Overview "${page.id}" references unknown page "${id}".`)
    if (getPageLocale(entry) !== locale)
      throw new Error(
        `Overview "${page.id}" references "${id}" from another locale.`
      )
    return entry
  })
}

export const getPageBreadcrumbs = (pages: Page[], page: Page) => {
  const segments = page.id === "index" ? [] : page.id.split("/")
  const ids = new Set([
    getHomeId(getPageLocale(page)),
    ...segments.map((_, index) => segments.slice(0, index + 1).join("/")),
  ])
  return [...ids].flatMap((id) => {
    const entry = pages.find((candidate) => candidate.id === id)
    return entry ? [{ label: entry.data.title, href: getPageHref(entry) }] : []
  })
}

export const getPageAlternates = (pages: Page[], page: Page) => {
  const key = page.data.translationKey
  if (!key) return []
  return pages
    .filter((entry) => entry.data.translationKey === key && isIndexable(entry))
    .map((entry) => ({ locale: getPageLocale(entry), href: getPageUrl(entry) }))
}

import { getPageUrl, siteUrl, type Page } from "@/lib/pages"

type Context = {
  name: string
  locale: string
  breadcrumbs: { label: string; href: string }[]
}

// Emits only facts present in the page data: no invented dates or authors.
export const getStructuredData = (
  page: Page,
  { name, locale, breadcrumbs }: Context
) => {
  const url = page.data.seo?.canonical ?? getPageUrl(page)
  const websiteId = new URL("/#website", siteUrl).href
  const dateModified = page.data.updatedAt?.toISOString()
  const graph: Record<string, unknown>[] = [
    {
      "@type": "WebSite",
      "@id": websiteId,
      url: new URL("/", siteUrl).href,
      name,
    },
    {
      "@type": page.data.type === "overview" ? "CollectionPage" : "WebPage",
      "@id": `${url}#webpage`,
      url,
      name: page.data.title,
      description: page.data.description,
      inLanguage: locale,
      isPartOf: { "@id": websiteId },
      ...(dateModified && { dateModified }),
      ...(breadcrumbs.length > 1 && {
        breadcrumb: { "@id": `${url}#breadcrumb` },
      }),
    },
  ]
  if (breadcrumbs.length > 1)
    graph.push({
      "@type": "BreadcrumbList",
      "@id": `${url}#breadcrumb`,
      itemListElement: breadcrumbs.map((item, index) => ({
        "@type": "ListItem",
        position: index + 1,
        name: item.label,
        item: new URL(item.href, siteUrl).href,
      })),
    })
  return { "@context": "https://schema.org", "@graph": graph }
}

---
import { getPages } from "@/lib/pages"
import LayoutRenderer from "@/components/layout-renderer.astro"

export async function getStaticPaths() {
  const pages = await getPages()
  return pages.map((page) => ({
    params: { page: page.id === "index" ? undefined : page.id },
    props: page,
  }))
}
---

<LayoutRenderer {...Astro.props} />

import type { APIRoute } from "astro"

import {
  getPageAlternates,
  getPages,
  getPageUrl,
  isIndexable,
} from "@/lib/pages"

export const prerender = true

const escape = (value: string) =>
  value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")

// Built from the validated pages collection, so noindex, canonical, updatedAt,
// and translated slugs come from the same frontmatter the HTML head uses.
export const GET: APIRoute = async () => {
  const pages = (await getPages()).filter(isIndexable)
  const urls = pages.map((page) => {
    const lastmod = page.data.updatedAt
      ? `<lastmod>${page.data.updatedAt.toISOString()}</lastmod>`
      : ""
    const alternates = getPageAlternates(pages, page)
      .map(
        ({ locale, href }) =>
          `<xhtml:link rel="alternate" hreflang="${locale}" href="${escape(href)}"/>`
      )
      .join("")
    return `<url><loc>${escape(getPageUrl(page))}</loc>${lastmod}${alternates}</url>`
  })
  return new Response(
    `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">${urls.join("")}</urlset>`,
    { headers: { "Content-Type": "application/xml; charset=utf-8" } }
  )
}

// The production URL comes from `site` in astro.config and locales from its
// `i18n` option. Only the website name lives here.
export const siteConfig = {
  name: "",
}

if (!siteConfig.name) {
  throw new Error("Set your website name in src/site.config.ts.")
}
